#!/usr/bin/env python3
import os, re, subprocess
from collections import defaultdict

REPO = "/bench/repo"
STORE_IMPORT = "github.com/usememos/memos/store"

# Persistent entity types (main domain structs, not Find/Update/Delete DTOs)
ENTITY_TYPES = {
    "Memo": "store/memo.go",
    "User": "store/user.go",
    "Attachment": "store/attachment.go",
    "Inbox": "store/inbox.go",
    "Reaction": "store/reaction.go",
    "IdentityProvider": "store/idp.go",
    "InstanceSetting": "store/instance_setting.go",
    "MemoRelation": "store/memo_relation.go",
    "MemoShare": "store/memo_share.go",
    "UserIdentity": "store/user_identity.go",
    "UserSetting": "store/user_setting.go",
    "AuthenticationConfigState": "store/auth_config.go",
}

# Also enumerate all structs in store root for completeness
STORE_ROOT = os.path.join(REPO, "store")
ALL_STORE_STRUCTS = []
for fn in sorted(os.listdir(STORE_ROOT)):
    if not fn.endswith(".go") or fn.endswith("_test.go"):
        continue
    path = os.path.join(STORE_ROOT, fn)
    with open(path) as f:
        for i, line in enumerate(f, 1):
            m = re.match(r'^type (\w+) struct', line)
            if m:
                ALL_STORE_STRUCTS.append((m.group(1), f"store/{fn}:{i}"))

# Get all Go files outside store layer
def is_store_layer(path):
    rel = os.path.relpath(path, REPO)
    return rel.startswith("store/") or rel.startswith("proto/gen/store/") or rel.startswith("proto/store/")

def get_go_packages():
    result = subprocess.run(
        ["go", "list", "-f", "{{.ImportPath}} {{.Dir}}", "./..."],
        cwd=REPO, capture_output=True, text=True
    )
    pkgs = {}
    for line in result.stdout.strip().splitlines():
        if not line.strip():
            continue
        parts = line.split(" ", 1)
        if len(parts) == 2:
            pkgs[parts[1]] = parts[0]
    return pkgs

def parse_import_alias(content, store_import=STORE_IMPORT):
    """Return list of local names used to refer to store package."""
    aliases = []
    # import block
    import_re = re.compile(
        r'import\s+(?:\(\s*([\s\S]*?)\s*\)|"([^"]+)"|(\w+)\s+"([^"]+)")',
        re.MULTILINE
    )
    for m in import_re.finditer(content):
        if m.group(2):  # single unaliased
            if m.group(2) == store_import:
                aliases.append("store")
        elif m.group(3) and m.group(4):  # single aliased
            if m.group(4) == store_import:
                aliases.append(m.group(3))
        elif m.group(1):  # block
            for line in m.group(1).splitlines():
                line = line.strip()
                if not line or line.startswith("//"):
                    continue
                am = re.match(r'(?:(\w+)\s+)?"([^"]+)"', line)
                if am and am.group(2) == store_import:
                    aliases.append(am.group(1) if am.group(1) else "store")
    return aliases

def find_entity_refs_in_file(path, entities):
    with open(path, errors='replace') as f:
        content = f.read()
    aliases = parse_import_alias(content)
    if not aliases:
        return set()
    found = set()
    for entity in entities:
        for alias in aliases:
            # word boundary after alias.Entity
            pattern = re.compile(r'\b' + re.escape(alias) + r'\.' + re.escape(entity) + r'\b')
            if pattern.search(content):
                found.add(entity)
    return found

# Main analysis
pkg_dirs = get_go_packages()
entity_refs = defaultdict(set)  # entity -> set of import paths
pkg_entity_refs = defaultdict(set)  # import path -> entities

for dir_path, import_path in sorted(pkg_dirs.items()):
    if import_path.startswith("github.com/usememos/memos/store"):
        continue  # skip entire store layer

    for root, dirs, files in os.walk(dir_path):
        # skip vendor etc
        for fn in files:
            if not fn.endswith(".go"):
                continue
            fpath = os.path.join(root, fn)
            refs = find_entity_refs_in_file(fpath, set(ENTITY_TYPES.keys()) | {s[0] for s in ALL_STORE_STRUCTS})
            for entity in refs:
                entity_refs[entity].add(import_path)
                pkg_entity_refs[import_path].add(entity)

# Print all store root structs
print("=== ALL STORE ROOT PACKAGE STRUCT DECLARATIONS ===")
for name, loc in ALL_STORE_STRUCTS:
    kind = "ENTITY" if name in ENTITY_TYPES else "DTO/INFRA"
    print(f"  {name:35s} [{kind:12s}] {loc}")

print("\n=== PERSISTENT ENTITY EXTERNAL PACKAGE COUNTS ===")
ranked = sorted(
    [(e, len(pkgs), ENTITY_TYPES.get(e, "?")) for e, pkgs in entity_refs.items() if e in ENTITY_TYPES],
    key=lambda x: (-x[1], x[0])
)
for entity, count, decl in ranked:
    print(f"  {entity:25s} {count:3d} pkgs  ({decl})")

print("\n=== TOP ENTITY DETAIL ===")
for entity, count, decl in ranked[:5]:
    print(f"\n--- {entity} ({count} external packages) ---")
    for pkg in sorted(entity_refs[entity]):
        print(f"  {pkg}")

# Also count Find/Update types for comparison
print("\n=== FIND/UPDATE/DELETE DTO EXTERNAL REFS (for comparison) ===")
dto_types = [s[0] for s in ALL_STORE_STRUCTS if s[0].startswith(("Find", "Update", "Delete")) or s[0] in ("RefreshTokenQueryResult", "PATQueryResult", "DeleteUserResult")]
dto_ranked = sorted([(e, len(entity_refs[e])) for e in dto_types if entity_refs[e]], key=lambda x: (-x[1], x[0]))
for e, c in dto_ranked[:10]:
    print(f"  {e:30s} {c:3d}")

# Value types
print("\n=== VALUE TYPES (RowStatus, Visibility, Role) ===")
for vt in ["RowStatus", "Visibility", "Role"]:
    c = len(entity_refs.get(vt, set()))
    print(f"  {vt:15s} {c:3d}")

