#!/usr/bin/perl
use strict;
use warnings;
use File::Find;
use File::Basename;

my $REPO = "/bench/repo";
my $STORE_IMPORT = "github.com/usememos/memos/store";

my %ENTITY_TYPES = (
    Memo => "store/memo.go",
    User => "store/user.go",
    Attachment => "store/attachment.go",
    Inbox => "store/inbox.go",
    Reaction => "store/reaction.go",
    IdentityProvider => "store/idp.go",
    InstanceSetting => "store/instance_setting.go",
    MemoRelation => "store/memo_relation.go",
    MemoShare => "store/memo_share.go",
    UserIdentity => "store/user_identity.go",
    UserSetting => "store/user_setting.go",
    AuthenticationConfigState => "store/auth_config.go",
);

# Enumerate all structs in store root
my @all_structs;
opendir(my $dh, "$REPO/store") or die $!;
for my $fn (sort readdir $dh) {
    next unless $fn =~ /\.go$/ && $fn !~ /_test\.go$/;
    open my $fh, "<", "$REPO/store/$fn" or next;
    my $line = 0;
    while (<$fh>) {
        $line++;
        if (/^type (\w+) struct/) {
            push @all_structs, [$1, "store/$fn:$line"];
        }
    }
    close $fh;
}
closedir $dh;

sub is_store_layer {
    my ($path) = @_;
    my $rel = $path;
    $rel =~ s/^\Q$REPO\E\///;
    return 1 if $rel =~ m{^store/};
    return 1 if $rel =~ m{^proto/gen/store/};
    return 1 if $rel =~ m{^proto/store/};
    return 0;
}

sub get_package_path {
    my ($dir) = @_;
    my $rel = $dir;
    $rel =~ s/^\Q$REPO\E\///;
    return "github.com/usememos/memos/$rel";
}

sub parse_import_aliases {
    my ($content) = @_;
    my @aliases;
    while ($content =~ /import\s+(?:\(\s*([\s\S]*?)\s*\)|"([^"]+)"|(\w+)\s+"([^"]+)")/g) {
        if (defined $2) {
            push @aliases, "store" if $2 eq $STORE_IMPORT;
        } elsif (defined $3 && defined $4) {
            push @aliases, $3 if $4 eq $STORE_IMPORT;
        } elsif (defined $1) {
            for my $line (split /\n/, $1) {
                $line =~ s/^\s+|\s+$//g;
                next if $line eq '' || $line =~ /^\/\//;
                if ($line =~ /^(?:(\w+)\s+)?"([^"]+)"/) {
                    my ($alias, $imp) = ($1, $2);
                    push @aliases, ($alias // "store") if $imp eq $STORE_IMPORT;
                }
            }
        }
    }
    return @aliases;
}

my %entity_refs;  # entity -> {pkg => 1}
my %pkg_dirs;     # dir -> 1

find(sub {
    return unless /\.go$/;
    return if /_test\.go$/;  # include tests actually - user wants package refs
    my $file = $File::Find::name;
    return if is_store_layer($file);
    my $dir = $File::Find::dir;
    $pkg_dirs{$dir} = 1;
}, $REPO);

# Re-find including tests
find(sub {
    return unless /\.go$/;
    my $file = $File::Find::name;
    return if is_store_layer($file);
    my $dir = dirname($file);
    open my $fh, "<", $file or return;
    local $/;
    my $content = <$fh>;
    close $fh;
    my @aliases = parse_import_aliases($content);
    return unless @aliases;
    my $pkg = get_package_path($dir);
    for my $entity (keys %ENTITY_TYPES) {
        for my $alias (@aliases) {
            if ($content =~ /\b\Q$alias\E\.\Q$entity\E\b/) {
                $entity_refs{$entity}{$pkg} = 1;
            }
        }
    }
    # value types
    for my $vt (qw(RowStatus Visibility Role)) {
        for my $alias (@aliases) {
            if ($content =~ /\b\Q$alias\E\.\Q$vt\E\b/) {
                $entity_refs{$vt}{$pkg} = 1;
            }
        }
    }
}, $REPO);

print "=== ALL STORE ROOT PACKAGE STRUCT DECLARATIONS ===\n";
for my $s (@all_structs) {
    my ($name, $loc) = @$s;
    my $kind = exists $ENTITY_TYPES{$name} ? "ENTITY" : "DTO/INFRA";
    printf "  %-35s [%-12s] %s\n", $name, $kind, $loc;
}

print "\n=== PERSISTENT ENTITY EXTERNAL PACKAGE COUNTS ===\n";
my @ranked = sort { ($entity_refs{$b}{scalar keys %{$entity_refs{$b}//{}}}) <=> ($entity_refs{$a}{scalar keys %{$entity_refs{$a}//{}}}) || $a cmp $b } keys %ENTITY_TYPES;
for my $entity (@ranked) {
    my $count = scalar keys %{$entity_refs{$entity} // {}};
    printf "  %-25s %3d pkgs  (%s)\n", $entity, $count, $ENTITY_TYPES{$entity};
}

print "\n=== TOP 2 ENTITY PACKAGE LISTS ===\n";
for my $i (0..1) {
    my $entity = $ranked[$i];
    my $count = scalar keys %{$entity_refs{$entity} // {}};
    print "\n--- $entity ($count external packages) ---\n";
    for my $pkg (sort keys %{$entity_refs{$entity} // {}}) {
        print "  $pkg\n";
    }
}

print "\n=== VALUE TYPES ===\n";
for my $vt (qw(RowStatus Visibility Role)) {
    my $count = scalar keys %{$entity_refs{$vt} // {}};
    printf "  %-15s %3d\n", $vt, $count;
}
